        if(e.employeeShares.mode!=='weights'&&((e.scopeType&&e.scopeType!=='role')||names.length))throw new Error('员工承担比例仅适用于角色取值');
        var weightMode=e.employeeShares.mode==='weights';
        var selectedRoles=weightMode&&names.length?Array.from(new Set(members.map(function(f){return f.role;}))):roles;
        var ordered=validateEmployeeShares(e.employeeShares,selectedRoles,weightMode?members:facts);
