      var name = (document.getElementById('ruleName') || {}).value || '未命名规则';
      var store = (document.getElementById('storeSelect') || {}).value || '未选择门店';
      var mode = (document.querySelector('input[name="allocationMode"]:checked') || {}).value || 'legacy_pool';
